CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE POLICY read_own_roles ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE TABLE public.shipping_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), config jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.shipping_settings TO authenticated;
GRANT ALL ON public.shipping_settings TO service_role;
ALTER TABLE public.shipping_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_shipping_settings ON public.shipping_settings FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.shipping_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid, items jsonb NOT NULL DEFAULT '[]', delivery_address jsonb, subtotal_cents integer NOT NULL DEFAULT 0 CHECK(subtotal_cents>=0), discount_cents integer NOT NULL DEFAULT 0 CHECK(discount_cents>=0), freight_cents integer CHECK(freight_cents>=0), payment_status text NOT NULL DEFAULT 'pending' CHECK(payment_status IN ('pending','approved','failed')), shipping_status text NOT NULL DEFAULT 'awaiting_payment' CHECK(shipping_status IN ('awaiting_payment','paid','awaiting_label','awaiting_label_payment','label_issued','ready_to_post','posted','delivered','logistics_failed')), provider_payment_id text UNIQUE, provider_shipment_id text UNIQUE, label_url text, tracking_code text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.shipping_orders TO authenticated;
GRANT ALL ON public.shipping_orders TO service_role;
ALTER TABLE public.shipping_orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_read_orders ON public.shipping_orders FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.shipping_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid REFERENCES public.shipping_orders(id), provider text NOT NULL, external_event_id text UNIQUE, kind text NOT NULL, state text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.shipping_events TO authenticated;
GRANT ALL ON public.shipping_events TO service_role;
ALTER TABLE public.shipping_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_read_events ON public.shipping_events FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));